#include "InheritedBase.inc"
#include <sofa/core/behavior/Mass.h>
double product(const Types::VecDeriv&a,const Types::VecDeriv&b){double s=0;for(size_t i=0;i<a.size();++i)for(int j=0;j<6;++j)s+=a[i][j]*b[i][j];return s;}
int main(int argc,char**argv){try{
 if(argc!=7)throw std::invalid_argument("SDK SCENE FRAME_PLUGIN BEAM_PLUGIN STEPS OUTPUT");
 sofa::simulation::graph::init();sofa::simpleapi::init();sofa::helper::system::PluginRepository.addFirstPath(std::string(argv[1])+"/lib");sofa::simulation::Simulation::theSimulation=sofa::simpleapi::createSimulation("DAG");if(!sofa::simpleapi::importPlugin(argv[3])||!sofa::simpleapi::importPlugin(argv[4]))throw std::runtime_error("plugin");auto root=sofa::simulation::node::load(argv[2]);if(!root)throw std::runtime_error("scene");sofa::simulation::node::initRoot(root.get());auto*body=root->getChild("Multilayer");auto*state=dynamic_cast<State*>(body->getMechanicalState());auto*ctx=static_cast<sofa::core::objectmodel::BaseContext*>(body);auto masses=ctx->getObjects<sofa::core::behavior::Mass<Types>>(sofa::core::objectmodel::BaseContext::Local);FF*beam=nullptr,*external=nullptr;for(auto*ff:ctx->getObjects<FF>(sofa::core::objectmodel::BaseContext::Local)){if(ff->getClassName()=="ConservativeBeam")beam=ff;else if(ff->getClassName()=="ConstantForceField")external=ff;else if(ff->getClassName()!="UniformMass")throw std::runtime_error("energy driver scope: single isotropic-mass rod only");}if(!state||!beam||!external||masses.size()!=1)throw std::runtime_error("energy objects");auto*mass=masses[0];int steps=std::stoi(argv[5]);if(steps<1||steps>120000)throw std::invalid_argument("step cap");std::ofstream file(argv[6]);if(!file)throw std::runtime_error("output");file<<std::setprecision(17)<<"time,U,K,W_external,D_mass,D_stiffness,D_implicit_linear_formula,residual\n";sofa::core::MechanicalParams mp;mp.setKFactor(1);mp.setBFactor(0);mp.setMFactor(0);double h=root->getDt(),work=0,dm=0,ds=0,dn=0,Uinitial=beam->getPotentialEnergy(&mp,*state->read(sofa::core::vec_id::read_access::position)),Kinitial=mass->getKineticEnergy(&mp,*state->read(sofa::core::vec_id::read_access::velocity));double residual=0,U1=Uinitial,K1=Kinitial;
 for(int step=1;step<=steps;++step){
  auto x0=state->read(sofa::core::vec_id::read_access::position)->getValue();auto v0=state->read(sofa::core::vec_id::read_access::velocity)->getValue();sofa::simulation::node::animate(root.get());auto x1=state->read(sofa::core::vec_id::read_access::position)->getValue();auto v1=state->read(sofa::core::vec_id::read_access::velocity)->getValue();U1=beam->getPotentialEnergy(&mp,*state->read(sofa::core::vec_id::read_access::position));K1=mass->getKineticEnergy(&mp,*state->read(sofa::core::vec_id::read_access::velocity));FF::DataVecDeriv velocity,difference,Jv,Mv,Mdv,fext;velocity.setValue(v1);auto dv=v1,dx=v1;for(size_t i=0;i<v1.size();++i){dv[i]-=v0[i];for(int j=0;j<6;++j)dx[i][j]*=h;}difference.setValue(dv);Jv.setValue(Types::VecDeriv(v1.size()));Mv.setValue(Types::VecDeriv(v1.size()));Mdv.setValue(Types::VecDeriv(v1.size()));fext.setValue(Types::VecDeriv(v1.size()));
  state->write(sofa::core::vec_id::write_access::position)->setValue(x0);beam->addDForce(&mp,Jv,velocity);mass->addMDx(&mp,Mv,velocity,1);mass->addMDx(&mp,Mdv,difference,1);FF::DataVecCoord previous;previous.setValue(x0);external->addForce(&mp,fext,previous,velocity);state->write(sofa::core::vec_id::write_access::position)->setValue(x1);
  work+=product(fext.getValue(),dx);double vJv=product(v1,Jv.getValue());dm+=2*h*product(v1,Mv.getValue());ds-=.1*h*vJv;dn+=.5*product(dv,Mdv.getValue())-.5*h*h*vJv;residual=(U1-Uinitial)+(K1-Kinitial)-work+dm+ds+dn;
  if(step%20==0)file<<root->getTime()<<','<<U1<<','<<K1<<','<<work<<','<<dm<<','<<ds<<','<<dn<<','<<residual<<'\n';
 }
 std::cout<<std::setprecision(17)<<"DYNAMIC_ENERGY {\"U\":"<<U1<<",\"K\":"<<K1<<",\"W_external\":"<<work<<",\"D_mass\":"<<dm<<",\"D_stiffness\":"<<ds<<",\"D_implicit_linear_formula\":"<<dn<<",\"unclosed_residual\":"<<residual<<",\"normalized_residual\":"<<residual/(std::abs(work)+1e-30)<<",\"steps\":"<<steps<<",\"dt\":"<<h<<"}"<<std::endl;
 sofa::simulation::node::unload(root);root.reset();sofa::simulation::Simulation::theSimulation.reset();sofa::simpleapi::cleanup();sofa::simulation::graph::cleanup();return 0;
}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<std::endl;return 1;}}
